import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { Line } from 'react-chartjs-2';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend,
} from 'chart.js';
import { useAuth } from '../context/AuthContext';
import { getHistory } from '../services/api';

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend);

const riskClass = (p) =>
  p?.includes('High') ? 'risk-high' : p?.includes('Moderate') ? 'risk-moderate' : 'risk-low';

export default function Dashboard() {
  const { user } = useAuth();
  const [history, setHistory] = useState([]);

  useEffect(() => {
    getHistory().then((r) => setHistory(r.data.history || [])).catch(() => {});
  }, []);

  const latest = history[0];
  const chartData = {
    labels: history.slice(0, 7).reverse().map((h) => new Date(h.createdAt).toLocaleDateString()),
    datasets: [
      {
        label: 'Confidence %',
        data: history.slice(0, 7).reverse().map((h) => h.confidence),
        borderColor: '#4f46e5',
        tension: 0.3,
      },
    ],
  };

  return (
    <div>
      <div className="card card-mw p-4 mb-4">
        <h2>Welcome, {user?.name || 'User'} 👋</h2>
        <p className="text-muted mb-0">AI-Based Mental Health Monitoring for Early Depression Prediction</p>
      </div>
      <div className="row g-3 mb-4">
        <div className="col-md-4">
          <div className="card card-mw p-3 h-100">
            <h6 className="text-muted">Depression Risk Status</h6>
            <h3 className={riskClass(latest?.prediction)}>{latest?.prediction || 'No assessment yet'}</h3>
          </div>
        </div>
        <div className="col-md-4">
          <div className="card card-mw p-3 h-100">
            <h6 className="text-muted">Confidence Score</h6>
            <h3>{latest?.confidence != null ? `${latest.confidence}%` : '—'}</h3>
          </div>
        </div>
        <div className="col-md-4">
          <div className="card card-mw p-3 h-100">
            <h6 className="text-muted">Total Assessments</h6>
            <h3>{history.length}</h3>
            <Link to="/assessment" className="btn btn-sm btn-primary mt-2">New Assessment</Link>
          </div>
        </div>
      </div>
      {latest && (
        <div className="card card-mw p-4 mb-4">
          <h5>Recent Assessment Summary</h5>
          <div className="row small">
            <div className="col-6 col-md-3">Sleep: {latest.sleep_score}</div>
            <div className="col-6 col-md-3">Stress: {latest.stress_score}</div>
            <div className="col-6 col-md-3">Walking: {latest.walking_pct}%</div>
            <div className="col-6 col-md-3">Activity: {latest.activity_level}</div>
          </div>
        </div>
      )}
      <div className="card card-mw p-4">
        <h5>Confidence Trend</h5>
        {history.length > 0 ? <Line data={chartData} /> : <p className="text-muted">Complete an assessment to see charts.</p>}
      </div>
    </div>
  );
}
